// static
bool StructTraits<::remoting::mojom::ClientCertificateDetails::DataView, ::remoting::mojom::ClientCertificateDetailsPtr>::Read(
    ::remoting::mojom::ClientCertificateDetails::DataView input,
    ::remoting::mojom::ClientCertificateDetailsPtr* output) {
  bool success = true;
  ::remoting::mojom::ClientCertificateDetailsPtr result(::remoting::mojom::ClientCertificateDetails::New());
  
      if (success && !input.ReadCertificate(&result->certificate))
        success = false;
      if (success && !input.ReadProviderName(&result->provider_name))
        success = false;
      if (success && !input.ReadAlgorithmPreferences(&result->algorithm_preferences))
        success = false;
      if (success) {
        result->private_key =
            input.TakePrivateKey<decltype(result->private_key)>();
      }
  *output = std::move(result);
  return success;
}

